-- Seed product_images only reference files that exist in the repository.
-- Real catalog product photos are imported through Product Import V2.








UPDATE product_specs
SET spec_label = spec_key
WHERE spec_label IS NULL OR spec_label = '';

UPDATE product_specs
SET filter_enabled = 1
WHERE LOWER(spec_key) IN (
  'cpu',
  'gpu',
  'vga',
  'ram',
  'storage',
  'ssd',
  'lưu trữ',
  'màn hình',
  'kích thước màn hình',
  'tần số quét',
  'refresh_rate',
  'display_size',
  'panel',
  'tấm nền',
  'socket',
  'nhân',
  'luồng',
  'vram',
  'dung lượng',
  'chuẩn kết nối'
);












